    monitors = image_patch.find("monitor")
    stands = image_patch.find("stand")

    if not monitors or not stands:
        return image_patch

    monitor_patches = []
    for monitor in monitors:
        for stand in stands:
            if monitor.overlaps_with(*stand.bbox()):
                monitor_patches.append(monitor)

    if not monitor_patches:
        return image_patch

    monitor_patches.sort(key=lambda m: m.horizontal_center)
    left_monitor = monitor_patches[0]

    top_monitors = [m for m in monitor_patches if m.vertical_center < left_monitor.vertical_center]
    if top_monitors:
        return top_monitors[0]

    return left_monitor

